 "content": "def transform(grid):
    """Fill the regions around the 3-colored cross with the parity-distance pattern."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    cross_r = next((r for r, row in enumerate(grid) if row and all(v == 3 for v in row)), None)
    cross_c = next((c for c in range(w) if all(grid[r][c] == 3 for r in range(h))), None)
    if cross_r is None or cross_c is None:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                continue
            x = abs(c - cross_c)
            y = abs(r - cross_r)
            if y % 2 == 1:
                colored = (x % 2 == 0 and x >= y + 1)
            else:
                colored = (x % 2 == 0) or (x % 2 == 1 and x <= y - 1)
            if colored:
                out[r][c] = 4
    return out
